\documentclass[11pt]{article}
\usepackage[margin=2.5cm]{geometry}
\usepackage{hyperref}

\title{Gallery Talk Notes: Bronze Mirrors of the Eastern Zhou}
\author{Friends of the Museum --- Docent Circle}
\date{April 2026}

\begin{document}
\maketitle

\section{Before the Talk}
Read the short catalogue essay on the museum website. The mirror
studied in this talk, accession number 1937.0412.6, sits in the
second case of the bronze gallery. Full provenance and conservation
records are in the
\href{https://www.citymuseum-example.org/permanent_collection}{permanent_collection}
database, which is open to the public.

\section{Talking Points}
Begin with the casting seams visible on the rim, then compare the
interlaced dragon pattern with the Chu examples on loan this spring.
Visitors usually ask about the green patina: it is stable carbonate
corrosion, not a modern coating, and the conservation record shows it
was already present in the 1937 acquisition photographs.

\section{Timing}
Allow ten minutes for the mirror itself and five for questions. If
the group is small, the rubbing station by the gallery door can be
used for a short hands-on segment.

\end{document}

